function getImgList(){  
    var str =html.match(/comic_images:\[(.*?)\]/);
    var list = str[1].match(/[^\']{10,}/g);
 if(list[0].substr(0,4)=="http"){
return list;
}
var piclist = new Array([list.length]);        
for (var i = 0; i < list.length; i++) {   
piclist[i] = "https://m.97manhua.com" + list[i];        
}       
    return piclist;
}

